+const fs = require("fs");
+const path = require("path");
+const os = require("os");
+const { walkDir } = require("/tmp/wd.cjs");
+
+const FileType = { File: 1, Directory: 2, SymbolicLink: 64 };
+
+class FileSystemIde {
+  constructor(workspaceDir) { this.workspaceDir = workspaceDir; }
+  pathSep() { return Promise.resolve(path.sep); }
+  readFile(filepath) { return Promise.resolve(fs.readFileSync(filepath, "utf8")); }
+  async listDir(dir) {
+    return fs.readdirSync(dir, { withFileTypes: true }).map((d) => [
+      d.name,
+      d.isDirectory() ? FileType.Directory : d.isSymbolicLink() ? FileType.SymbolicLink : FileType.File,
+    ]);
+  }
+}
+
+let TEST_DIR;
+function setUp() { TEST_DIR = fs.mkdtempSync(path.join(os.tmpdir(), "walk-")); }
+function tearDown() { fs.rmSync(TEST_DIR, { recursive: true, force: true }); }
+function addToTestDir(items) {
+  for (const it of items) {
+    let name, content;
+    if (Array.isArray(it)) { name = it[0]; content = it[1]; }
+    else { name = it; content = null; }
+    const p = path.join(TEST_DIR, name);
+    if (name.endsWith("/")) { fs.mkdirSync(p, { recursive: true }); }
+    else {
+      fs.mkdirSync(path.dirname(p), { recursive: true });
+      fs.writeFileSync(p, content ?? "");
+    }
+  }
+}
+
+let pass = 0, fail = 0;
+async function run(desc, files, toExist, toNotExist, options) {
+  setUp();
+  try {
+    addToTestDir(files);
+    const ide = new FileSystemIde(TEST_DIR);
+    const result = await walkDir(TEST_DIR, ide, { returnRelativePaths: true, ...options });
+    let ok = true, msg = "";
+    for (const p of toExist) if (!result.includes(p)) { ok = false; msg += `\n   missing: ${p}`; }
+    for (const p of toNotExist) if (result.includes(p)) { ok = false; msg += `\n   should not have: ${p}`; }
+    if (ok) { pass++; console.log("PASS:", desc); }
+    else { fail++; console.log("FAIL:", desc, msg, "\n   got:", JSON.stringify(result)); }
+  } finally { tearDown(); }
+}
+
+async function runEqual(desc, files, expected, options) {
+  setUp();
+  try {
+    addToTestDir(files);
+    const ide = new FileSystemIde(TEST_DIR);
+    const result = await walkDir(TEST_DIR, ide, { returnRelativePaths: true, ...options });
+    const ok = JSON.stringify(result) === JSON.stringify(expected);
+    if (ok) { pass++; console.log("PASS:", desc); }
+    else { fail++; console.log("FAIL:", desc, "\n   expected:", JSON.stringify(expected), "\n   got:", JSON.stringify(result)); }
+  } finally { tearDown(); }
+}
+
+(async () => {
+  // empty dir
+  await runEqual("empty dir -> []", [], []);
+  // flat dir sorted
+  await runEqual("flat dir sorted", ["a.txt", "b.py", "c.ts"], ["a.txt", "b.py", "c.ts"]);
+  // reverse insertion still sorted
+  await runEqual("flat dir sorted (reverse insert)", ["c.ts", "b.py", "a.txt"], ["a.txt", "b.py", "c.ts"]);
+  // ignore in flat
