+    ["a.py"], ["b.txt","c/e.py","c/d.txt"]);
+  // wildcards
+  await run("wildcards *.txt *.py", [[".gitignore","*.txt\n*.py"],"a.txt","b.py","c.ts","d/","d/e.txt","d/f.py","d/g.ts"],
+    ["c.ts","d/g.ts"], ["a.txt","b.py","d/e.txt","d/f.py"]);
+  // directory ignore
+  await run("directory ignore ignored_dir/", [[".gitignore","ignored_dir/"],"a.txt","ignored_dir/","ignored_dir/b.txt","ignored_dir/c/","ignored_dir/c/d.py"],
