+  // subdir gitignore only applies to subdir
+  await run("subdir gitignore only in subdir", [[".gitignore","abc"],"a.txt","abc","xyz/",["xyz/.gitignore","xyz"],"xyz/b.txt","xyz/c/","xyz/c/d.py","xyz/xyz"],
+    ["a.txt","xyz/b.txt","xyz/c/d.py"], ["abc","xyz/xyz"]);
+  // complex patterns
+  await run("complex patterns", [[".gitignore","*.what\n!important.what\ntemp/\n/root_only.txt"],"a.what","important.what","root_only.txt","subdir/","subdir/root_only.txt","subdir/b.what","temp/","temp/c.txt"],
+    ["important.what","subdir/root_only.txt"], ["a.what","root_only.txt","subdir/b.what","temp/c.txt"]);
+  // gitignore + continueignore
+  await run("gitignore + continueignore", [[".gitignore","*.py"],[".continueignore","*.ts"],"a.txt","b.py","c.ts","d.js"],
+    ["a.txt","d.js"], ["b.py","c.ts"]);
+  // onlyDirs
+  await run("onlyDirs", ["a.txt","b.py","c.ts","d/","d/e.txt","d/f.py","d/g/","d/g/h.ts"],
+    ["d","d/g"], ["a.txt","b.py","c.ts","d/e.txt","d/f.py","d/g/h.ts"], { onlyDirs: true });
+  // absolute paths
+  {
+    setUp();
+    try {
+      addToTestDir(["a.txt","b/","b/c.txt"]);
+      const ide = new FileSystemIde(TEST_DIR);
+      const result = await walkDir(TEST_DIR, ide, { returnRelativePaths: false });
+      const e1 = path.join(TEST_DIR, "a.txt"), e2 = path.join(TEST_DIR, "b", "c.txt");
+      const ok = result.includes(e1) && result.includes(e2);
